// Semantic visual identity for every tower family.
export const FAMILY_EFFECTS={basic:'element',clone:'mirror',helix:'ice',chain:'lightning',quark:'plasma',life:'leaf',magic:'arcane',bomb:'shell',smith:'forge',poison:'venom',vapor:'steam',hydro:'geyser',disease:'plague',flame:'fire',boomerang:'glaive',well:'water',zealot:'radiant',quaker:'rock',laser:'laser',oblivion:'void',polar:'ice',drowning:'water',orbit:'orbit',napalm:'napalm',voodoo:'spirit',muck:'mud',corrosion:'acid',roots:'roots',nova:'nova',gold:'gold',storm:'lightning',hail:'hail',tidal:'water',enchant:'rune',impulse:'comet',golem:'bone'};
export function attackStyle(def){const family=FAMILY_EFFECTS[def.family]||'element';if(family!=='element')return family;if(def.element==='composite')return /Cannon/.test(def.name)?'shell':def.name==='Periodic Tower of the Elements'?'prismatic':'arrow';return {fire:'fire',nature:'leaf',earth:'rock',light:'radiant',darkness:'void',water:'water'}[def.element]||'prismatic';}
